module RoundingUnit(
  input  [22:0] io_in,
  input         io_roundIn,
                io_stickyIn,
                io_signIn,
  input  [2:0]  io_rm,
  output [22:0] io_out,
  output        io_inexact,
                io_cout
);

  wire inexact = io_roundIn | io_stickyIn;
  wire r_up =
    io_rm == 3'h4
      ? io_roundIn
      : io_rm == 3'h2
          ? inexact & io_signIn
          : io_rm == 3'h3
              ? inexact & ~io_signIn
              : io_rm != 3'h1 & io_rm == 3'h0
                & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  assign io_out = r_up ? io_in + 23'h1 : io_in;
  assign io_inexact = inexact;
  assign io_cout = r_up & (&io_in);
endmodule

module TininessRounder(
  input         io_in_sign,
  input  [26:0] io_in_sig,
  input  [2:0]  io_rm,
  output        io_tininess
);

  wire _rounder_io_cout;
  RoundingUnit rounder (
    .io_in       (io_in_sig[24:2]),
    .io_roundIn  (io_in_sig[1]),
    .io_stickyIn (io_in_sig[0]),
    .io_signIn   (io_in_sign),
    .io_rm       (io_rm),
    .io_out      (/* unused */),
    .io_inexact  (/* unused */),
    .io_cout     (_rounder_io_cout)
  );
  assign io_tininess =
    io_in_sig[26:25] == 2'h0 | io_in_sig[26:25] == 2'h1 & ~_rounder_io_cout;
endmodule

module RoundingUnitWithSR(
  input  [22:0] io_in,
  input         io_roundIn,
                io_stickyIn,
                io_signIn,
  input  [2:0]  io_rm,
  input  [15:0] io_in_tail,
                io_randomnum,
  output [22:0] io_out,
  output        io_cout
);

  wire        inexact = io_roundIn | io_stickyIn;
  wire [16:0] sum = {1'h0, io_randomnum} + {1'h0, io_in_tail};
  wire        _r_up_T_11 =
    io_rm != 3'h1 & io_rm == 3'h0
    & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  wire [7:0]  _GEN =
    {{_r_up_T_11},
     {io_randomnum < io_in_tail},
     {sum[16]},
     {io_roundIn},
     {inexact & io_signIn},
     {inexact & ~io_signIn},
     {_r_up_T_11},
     {_r_up_T_11}};
  assign io_out = _GEN[io_rm] ? io_in + 23'h1 : io_in;
  assign io_cout = _GEN[io_rm] & (&io_in);
endmodule

module NormAlignInner(
  input         clock,
                reset,
  output        io_in_ready,
  input         io_in_valid,
  input  [34:0] io_in_bits_sigSigned,
  input  [5:0]  io_in_bits_baseExp,
  input  [2:0]  io_in_bits_rm,
  input  [3:0]  io_in_bits_tcCtrl_dataType,
                io_in_bits_tcCtrl_dataTypeB,
  input         io_in_bits_tcCtrl_mixPrecision,
                io_in_bits_tcCtrl_Sparisity,
  input  [31:0] io_in_bits_tcCtrl_DAddress,
  input         io_in_bits_tcCtrl_clear,
  input  [7:0]  io_in_bits_tcCtrl_M,
                io_in_bits_tcCtrl_N,
                io_in_bits_tcCtrl_K,
  input  [3:0]  io_in_bits_tcCtrl_OutputD_Idx_m_mix,
  input  [4:0]  io_in_bits_tcCtrl_OutputD_Idx_n_mix,
  input  [5:0]  io_in_bits_tcCtrl_OutputD_Idx_m_f32,
                io_in_bits_tcCtrl_OutputD_Idx_n_f32,
  input  [31:0] io_in_bits_throughout_c,
  input  [2:0]  io_in_bits_throughout_rm,
  input  [3:0]  io_in_bits_randomnum,
  input         io_out_ready,
  output        io_out_valid,
  output [31:0] io_out_bits_result,
  output [3:0]  io_out_bits_tcCtrl_dataType,
                io_out_bits_tcCtrl_dataTypeB,
  output        io_out_bits_tcCtrl_mixPrecision,
                io_out_bits_tcCtrl_Sparisity,
  output [31:0] io_out_bits_tcCtrl_DAddress,
  output        io_out_bits_tcCtrl_clear,
  output [7:0]  io_out_bits_tcCtrl_M,
                io_out_bits_tcCtrl_N,
                io_out_bits_tcCtrl_K,
  output [3:0]  io_out_bits_tcCtrl_OutputD_Idx_m_mix,
  output [4:0]  io_out_bits_tcCtrl_OutputD_Idx_n_mix,
  output [5:0]  io_out_bits_tcCtrl_OutputD_Idx_m_f32,
                io_out_bits_tcCtrl_OutputD_Idx_n_f32,
  output [31:0] io_out_bits_throughout_c,
  output [2:0]  io_out_bits_throughout_rm
);

  wire        s1_ready;
  wire [22:0] _rounder_io_out;
  wire        _rounder_io_cout;
  reg         s0Pipe_rValid;
  reg         s0Pipe_rBits_sign;
  reg  [2:0]  s0Pipe_rBits_rm;
  reg  [7:0]  s0Pipe_rBits_exp;
  reg  [27:0] s0Pipe_rBits_sig;
  reg  [3:0]  s0Pipe_rBits_randomnum;
  reg  [3:0]  s0Pipe_rBits_tcCtrl_dataType;
  reg  [3:0]  s0Pipe_rBits_tcCtrl_dataTypeB;
  reg         s0Pipe_rBits_tcCtrl_mixPrecision;
  reg         s0Pipe_rBits_tcCtrl_Sparisity;
  reg  [31:0] s0Pipe_rBits_tcCtrl_DAddress;
  reg         s0Pipe_rBits_tcCtrl_clear;
  reg  [7:0]  s0Pipe_rBits_tcCtrl_M;
  reg  [7:0]  s0Pipe_rBits_tcCtrl_N;
  reg  [7:0]  s0Pipe_rBits_tcCtrl_K;
  reg  [3:0]  s0Pipe_rBits_tcCtrl_OutputD_Idx_m_mix;
  reg  [4:0]  s0Pipe_rBits_tcCtrl_OutputD_Idx_n_mix;
  reg  [5:0]  s0Pipe_rBits_tcCtrl_OutputD_Idx_m_f32;
  reg  [5:0]  s0Pipe_rBits_tcCtrl_OutputD_Idx_n_f32;
  reg  [31:0] s0Pipe_rBits_throughout_c;
  reg  [2:0]  s0Pipe_rBits_throughout_rm;
  wire        s0_ready = ~s0Pipe_rValid | s1_ready;
  reg         s1Pipe_rValid;
  reg  [31:0] s1Pipe_rBits_result;
  reg  [3:0]  s1Pipe_rBits_tcCtrl_dataType;
  reg  [3:0]  s1Pipe_rBits_tcCtrl_dataTypeB;
  reg         s1Pipe_rBits_tcCtrl_mixPrecision;
  reg         s1Pipe_rBits_tcCtrl_Sparisity;
  reg  [31:0] s1Pipe_rBits_tcCtrl_DAddress;
  reg         s1Pipe_rBits_tcCtrl_clear;
  reg  [7:0]  s1Pipe_rBits_tcCtrl_M;
  reg  [7:0]  s1Pipe_rBits_tcCtrl_N;
  reg  [7:0]  s1Pipe_rBits_tcCtrl_K;
  reg  [3:0]  s1Pipe_rBits_tcCtrl_OutputD_Idx_m_mix;
  reg  [4:0]  s1Pipe_rBits_tcCtrl_OutputD_Idx_n_mix;
  reg  [5:0]  s1Pipe_rBits_tcCtrl_OutputD_Idx_m_f32;
  reg  [5:0]  s1Pipe_rBits_tcCtrl_OutputD_Idx_n_f32;
  reg  [31:0] s1Pipe_rBits_throughout_c;
  reg  [2:0]  s1Pipe_rBits_throughout_rm;
  assign s1_ready = ~s1Pipe_rValid | io_out_ready;
  always @(posedge clock) begin
    automatic logic _s0Pipe_T;
    automatic logic _s1Pipe_T;
    _s0Pipe_T = s0_ready & io_in_valid;
    _s1Pipe_T = s1_ready & s0Pipe_rValid;
    if (reset) begin
      s0Pipe_rValid <= 1'h0;
      s1Pipe_rValid <= 1'h0;
    end
    else begin
      s0Pipe_rValid <= _s0Pipe_T | ~(s1_ready & s0Pipe_rValid) & s0Pipe_rValid;
      s1Pipe_rValid <= _s1Pipe_T | ~(io_out_ready & s1Pipe_rValid) & s1Pipe_rValid;
    end
    if (_s0Pipe_T) begin
      automatic logic [33:0] _rawSig_T_3 =
        io_in_bits_sigSigned[34]
          ? ~(io_in_bits_sigSigned[33:0]) + 34'h1
          : io_in_bits_sigSigned[33:0];
      automatic logic [5:0]  lzCount =
        _rawSig_T_3[33]
          ? 6'h0
          : _rawSig_T_3[32]
              ? 6'h1
              : _rawSig_T_3[31]
                  ? 6'h2
                  : _rawSig_T_3[30]
                      ? 6'h3
                      : _rawSig_T_3[29]
                          ? 6'h4
                          : _rawSig_T_3[28]
                              ? 6'h5
                              : _rawSig_T_3[27]
                                  ? 6'h6
                                  : _rawSig_T_3[26]
                                      ? 6'h7
                                      : _rawSig_T_3[25]
                                          ? 6'h8
                                          : _rawSig_T_3[24]
                                              ? 6'h9
                                              : _rawSig_T_3[23]
                                                  ? 6'hA
                                                  : _rawSig_T_3[22]
                                                      ? 6'hB
                                                      : _rawSig_T_3[21]
                                                          ? 6'hC
                                                          : _rawSig_T_3[20]
                                                              ? 6'hD
                                                              : _rawSig_T_3[19]
                                                                  ? 6'hE
                                                                  : _rawSig_T_3[18]
                                                                      ? 6'hF
                                                                      : _rawSig_T_3[17]
                                                                          ? 6'h10
                                                                          : _rawSig_T_3[16]
                                                                              ? 6'h11
                                                                              : _rawSig_T_3[15]
                                                                                  ? 6'h12
                                                                                  : _rawSig_T_3[14]
                                                                                      ? 6'h13
                                                                                      : _rawSig_T_3[13]
                                                                                          ? 6'h14
                                                                                          : _rawSig_T_3[12]
                                                                                              ? 6'h15
                                                                                              : _rawSig_T_3[11]
                                                                                                  ? 6'h16
                                                                                                  : _rawSig_T_3[10]
                                                                                                      ? 6'h17
                                                                                                      : _rawSig_T_3[9]
                                                                                                          ? 6'h18
                                                                                                          : _rawSig_T_3[8]
                                                                                                              ? 6'h19
                                                                                                              : _rawSig_T_3[7]
                                                                                                                  ? 6'h1A
                                                                                                                  : _rawSig_T_3[6]
                                                                                                                      ? 6'h1B
                                                                                                                      : _rawSig_T_3[5]
                                                                                                                          ? 6'h1C
                                                                                                                          : _rawSig_T_3[4]
                                                                                                                              ? 6'h1D
                                                                                                                              : _rawSig_T_3[3]
                                                                                                                                  ? 6'h1E
                                                                                                                                  : _rawSig_T_3[2]
                                                                                                                                      ? 6'h1F
                                                                                                                                      : _rawSig_T_3[1]
                                                                                                                                          ? 6'h20
                                                                                                                                          : _rawSig_T_3[0]
                                                                                                                                              ? 6'h21
                                                                                                                                              : 6'h22;
      automatic logic [96:0] _shifted_T = {63'h0, _rawSig_T_3} << lzCount;
      s0Pipe_rBits_sign <= io_in_bits_sigSigned[34];
      s0Pipe_rBits_rm <= io_in_bits_rm;
      s0Pipe_rBits_exp <= {2'h0, io_in_bits_baseExp} - 8'h79 - {2'h0, lzCount} - 8'h1E;
      s0Pipe_rBits_sig <= _shifted_T[33:6];
      s0Pipe_rBits_randomnum <= io_in_bits_randomnum;
      s0Pipe_rBits_tcCtrl_dataType <= io_in_bits_tcCtrl_dataType;
      s0Pipe_rBits_tcCtrl_dataTypeB <= io_in_bits_tcCtrl_dataTypeB;
      s0Pipe_rBits_tcCtrl_mixPrecision <= io_in_bits_tcCtrl_mixPrecision;
      s0Pipe_rBits_tcCtrl_Sparisity <= io_in_bits_tcCtrl_Sparisity;
      s0Pipe_rBits_tcCtrl_DAddress <= io_in_bits_tcCtrl_DAddress;
      s0Pipe_rBits_tcCtrl_clear <= io_in_bits_tcCtrl_clear;
      s0Pipe_rBits_tcCtrl_M <= io_in_bits_tcCtrl_M;
      s0Pipe_rBits_tcCtrl_N <= io_in_bits_tcCtrl_N;
      s0Pipe_rBits_tcCtrl_K <= io_in_bits_tcCtrl_K;
      s0Pipe_rBits_tcCtrl_OutputD_Idx_m_mix <= io_in_bits_tcCtrl_OutputD_Idx_m_mix;
      s0Pipe_rBits_tcCtrl_OutputD_Idx_n_mix <= io_in_bits_tcCtrl_OutputD_Idx_n_mix;
      s0Pipe_rBits_tcCtrl_OutputD_Idx_m_f32 <= io_in_bits_tcCtrl_OutputD_Idx_m_f32;
      s0Pipe_rBits_tcCtrl_OutputD_Idx_n_f32 <= io_in_bits_tcCtrl_OutputD_Idx_n_f32;
      s0Pipe_rBits_throughout_c <= io_in_bits_throughout_c;
      s0Pipe_rBits_throughout_rm <= io_in_bits_throughout_rm;
    end
    if (_s1Pipe_T) begin
      automatic logic commonOf =
        _rounder_io_cout ? s0Pipe_rBits_exp == 8'hFE : (&s0Pipe_rBits_exp);
      automatic logic rmin =
        s0Pipe_rBits_rm == 3'h1 | s0Pipe_rBits_rm == 3'h2 & ~s0Pipe_rBits_sign
        | s0Pipe_rBits_rm == 3'h3 & s0Pipe_rBits_sign;
      s1Pipe_rBits_result <=
        {s0Pipe_rBits_sign,
         commonOf ? {7'h7F, ~rmin} : s0Pipe_rBits_exp + {7'h0, _rounder_io_cout},
         commonOf ? {23{rmin}} : _rounder_io_out};
      s1Pipe_rBits_tcCtrl_dataType <= s0Pipe_rBits_tcCtrl_dataType;
      s1Pipe_rBits_tcCtrl_dataTypeB <= s0Pipe_rBits_tcCtrl_dataTypeB;
      s1Pipe_rBits_tcCtrl_mixPrecision <= s0Pipe_rBits_tcCtrl_mixPrecision;
      s1Pipe_rBits_tcCtrl_Sparisity <= s0Pipe_rBits_tcCtrl_Sparisity;
      s1Pipe_rBits_tcCtrl_DAddress <= s0Pipe_rBits_tcCtrl_DAddress;
      s1Pipe_rBits_tcCtrl_clear <= s0Pipe_rBits_tcCtrl_clear;
      s1Pipe_rBits_tcCtrl_M <= s0Pipe_rBits_tcCtrl_M;
      s1Pipe_rBits_tcCtrl_N <= s0Pipe_rBits_tcCtrl_N;
      s1Pipe_rBits_tcCtrl_K <= s0Pipe_rBits_tcCtrl_K;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_m_mix <= s0Pipe_rBits_tcCtrl_OutputD_Idx_m_mix;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_n_mix <= s0Pipe_rBits_tcCtrl_OutputD_Idx_n_mix;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_m_f32 <= s0Pipe_rBits_tcCtrl_OutputD_Idx_m_f32;
      s1Pipe_rBits_tcCtrl_OutputD_Idx_n_f32 <= s0Pipe_rBits_tcCtrl_OutputD_Idx_n_f32;
      s1Pipe_rBits_throughout_c <= s0Pipe_rBits_throughout_c;
      s1Pipe_rBits_throughout_rm <= s0Pipe_rBits_throughout_rm;
    end
  end // always @(posedge)
  TininessRounder tininessRounder (
    .io_in_sign  (s0Pipe_rBits_sign),
    .io_in_sig   (s0Pipe_rBits_sig[26:0]),
    .io_rm       (s0Pipe_rBits_rm),
    .io_tininess (/* unused */)
  );
  RoundingUnitWithSR rounder (
    .io_in        (s0Pipe_rBits_sig[26:4]),
    .io_roundIn   (s0Pipe_rBits_sig[3]),
    .io_stickyIn  (|(s0Pipe_rBits_sig[2:0])),
    .io_signIn    (s0Pipe_rBits_sign),
    .io_rm        (s0Pipe_rBits_rm),
    .io_in_tail   ({12'h0, s0Pipe_rBits_sig[3:0]}),
    .io_randomnum ({12'h0, s0Pipe_rBits_randomnum}),
    .io_out       (_rounder_io_out),
    .io_cout      (_rounder_io_cout)
  );
  assign io_in_ready = s0_ready;
  assign io_out_valid = s1Pipe_rValid;
  assign io_out_bits_result = s1Pipe_rBits_result;
  assign io_out_bits_tcCtrl_dataType = s1Pipe_rBits_tcCtrl_dataType;
  assign io_out_bits_tcCtrl_dataTypeB = s1Pipe_rBits_tcCtrl_dataTypeB;
  assign io_out_bits_tcCtrl_mixPrecision = s1Pipe_rBits_tcCtrl_mixPrecision;
  assign io_out_bits_tcCtrl_Sparisity = s1Pipe_rBits_tcCtrl_Sparisity;
  assign io_out_bits_tcCtrl_DAddress = s1Pipe_rBits_tcCtrl_DAddress;
  assign io_out_bits_tcCtrl_clear = s1Pipe_rBits_tcCtrl_clear;
  assign io_out_bits_tcCtrl_M = s1Pipe_rBits_tcCtrl_M;
  assign io_out_bits_tcCtrl_N = s1Pipe_rBits_tcCtrl_N;
  assign io_out_bits_tcCtrl_K = s1Pipe_rBits_tcCtrl_K;
  assign io_out_bits_tcCtrl_OutputD_Idx_m_mix = s1Pipe_rBits_tcCtrl_OutputD_Idx_m_mix;
  assign io_out_bits_tcCtrl_OutputD_Idx_n_mix = s1Pipe_rBits_tcCtrl_OutputD_Idx_n_mix;
  assign io_out_bits_tcCtrl_OutputD_Idx_m_f32 = s1Pipe_rBits_tcCtrl_OutputD_Idx_m_f32;
  assign io_out_bits_tcCtrl_OutputD_Idx_n_f32 = s1Pipe_rBits_tcCtrl_OutputD_Idx_n_f32;
  assign io_out_bits_throughout_c = s1Pipe_rBits_throughout_c;
  assign io_out_bits_throughout_rm = s1Pipe_rBits_throughout_rm;
