module FP16toFP32Converter(
  input  [15:0] io_in,
  output [31:0] io_out
);

  wire isZero = io_in[14:10] == 5'h0 & io_in[9:0] == 10'h0;
  assign io_out =
    {io_in[15],
     isZero ? 8'h0 : {3'h0, io_in[14:10]} + 8'h70,
     isZero ? 23'h0 : {io_in[9:0], 13'h0}};
endmodule

module RoundingUnit_1(
  input  [9:0] io_in,
  input        io_roundIn,
               io_stickyIn,
               io_signIn,
  input  [2:0] io_rm,
  output [9:0] io_out,
  output       io_cout
);

  wire inexact = io_roundIn | io_stickyIn;
  wire r_up =
    io_rm == 3'h4
      ? io_roundIn
      : io_rm == 3'h2
          ? inexact & io_signIn
          : io_rm == 3'h3
              ? inexact & ~io_signIn
              : io_rm != 3'h1 & io_rm == 3'h0
                & (io_roundIn & io_stickyIn | io_roundIn & ~io_stickyIn & io_in[0]);
  assign io_out = r_up ? io_in + 10'h1 : io_in;
  assign io_cout = r_up & (&io_in);
endmodule

module ShiftRightJam(
  input  [11:0] io_in,
  input  [7:0]  io_shamt,
  output [11:0] io_out,
  output        io_sticky
);

  wire        exceed_max_shift = io_shamt > 8'hC;
  wire [15:0] _sticky_mask_T = 16'h1 << io_shamt[3:0];
  assign io_out = exceed_max_shift ? 12'h0 : io_in >> io_shamt;
  assign io_sticky = |(io_in & (_sticky_mask_T[11:0] - 12'h1 | {12{exceed_max_shift}}));
endmodule

module FPDownConverter(
  input  [31:0] io_in,
  input  [2:0]  io_rm,
  output [15:0] io_result
);

  wire [9:0]  _subnormal_rounder_io_out;
  wire        _subnormal_rounder_io_cout;
  wire [11:0] _shiftRightJam_io_out;
  wire        _shiftRightJam_io_sticky;
  wire [9:0]  _normal_rounder_io_out;
  wire        _normal_rounder_io_cout;
  wire [8:0]  _down_exp_T_1 = {1'h0, io_in[30:23]} - 9'h70;
  wire        normal_of =
    _normal_rounder_io_cout
      ? $signed(_down_exp_T_1) > 9'sh1D
      : $signed(_down_exp_T_1) > 9'sh1E;
  wire        may_be_subnormal = $signed(_down_exp_T_1) < 9'sh1;
  wire        rmin =
    io_rm == 3'h1 | io_rm == 3'h2 & ~(io_in[31]) | io_rm == 3'h3 & io_in[31];
  wire        _GEN = may_be_subnormal | normal_of;
  wire [4:0]  _common_exp_T_9 =
    (~may_be_subnormal & normal_of ? {4'hF, ~rmin} : 5'h0)
    | (_GEN ? 5'h0 : _normal_rounder_io_cout ? io_in[27:23] - 5'hF : _down_exp_T_1[4:0]);
  RoundingUnit_1 normal_rounder (
    .io_in       (io_in[22:13]),
    .io_roundIn  (io_in[12]),
    .io_stickyIn (|(io_in[11:0])),
    .io_signIn   (io_in[31]),
    .io_rm       (io_rm),
    .io_out      (_normal_rounder_io_out),
    .io_cout     (_normal_rounder_io_cout)
  );
  ShiftRightJam shiftRightJam (
    .io_in     ({|(io_in[30:23]), io_in[22:12]}),
    .io_shamt  (8'h71 - io_in[30:23]),
    .io_out    (_shiftRightJam_io_out),
    .io_sticky (_shiftRightJam_io_sticky)
  );
  RoundingUnit_1 subnormal_rounder (
    .io_in       (_shiftRightJam_io_out[10:1]),
    .io_roundIn  (_shiftRightJam_io_out[0]),
    .io_stickyIn (_shiftRightJam_io_sticky | (|(io_in[11:0]))),
    .io_signIn   (io_in[31]),
    .io_rm       (io_rm),
    .io_out      (_subnormal_rounder_io_out),
    .io_cout     (_subnormal_rounder_io_cout)
  );
  assign io_result =
    {~((&(io_in[30:23])) & (|(io_in[22:0]))) & io_in[31],
     {5{&(io_in[30:23])}}
       | ((&(io_in[30:23]))
            ? 5'h0
            : {_common_exp_T_9[4:1],
               _common_exp_T_9[0] | may_be_subnormal & _subnormal_rounder_io_cout}),
     ((&(io_in[30:23])) ? {|(io_in[22:0]), 9'h0} : 10'h0)
       | ((&(io_in[30:23]))
            ? 10'h0
            : {10{~may_be_subnormal & normal_of & rmin}}
              | (_GEN ? 10'h0 : _normal_rounder_io_out)
              | (may_be_subnormal ? _subnormal_rounder_io_out : 10'h0))};
endmodule

module FPToFP(
  input  [31:0] io_in,
  input  [2:0]  io_rm,
  output [15:0] io_result
);

  FPDownConverter converter (
    .io_in     (io_in),
    .io_rm     (io_rm),
    .io_result (io_result)
  );
endmodule

module FP32toFP16Converter(
