  assign io_out =
    io_in[24]
      ? 5'h0
      : io_in[23]
          ? 5'h1
          : io_in[22]
              ? 5'h2
              : io_in[21]
                  ? 5'h3
                  : io_in[20]
                      ? 5'h4
                      : io_in[19]
