                                  : io_in[16]
                                      ? 5'h8
                                      : io_in[15]
                                          ? 5'h9
                                          : io_in[14]
                                              ? 5'hA
                                              : io_in[13]
                                                  ? 5'hB
                                                  : io_in[12]
                                                      ? 5'hC
                                                      : io_in[11]
                                                          ? 5'hD
                                                          : io_in[10]
                                                              ? 5'hE
                                                              : io_in[9]
                                                                  ? 5'hF
                                                                  : io_in[8]
                                                                      ? 5'h10
                                                                      : io_in[7]
                                                                          ? 5'h11
                                                                          : io_in[6]
                                                                              ? 5'h12
